internal final class NDXVendTableTransferProcess extends NDXTransferToD365 implements NDXTransferToD365Interface
{
}

Method.Source:
private void writeVendTable(Niedax.AX.TableRecordModels.TableRecord _record)
{
    System.Exception ex;

    Niedax.AX.TableRecordModels.VendTable vendTable = _record;
    VendTable lVendTable;
    AccountNum accountnum = '';

    str message = strFmt("VendTable %1 entered on %2", VendTable.ToString(), this.environment);

    try
    {
        accountnum = vendTable.Accountnum;

        lVendTable = VendTable::find(accountnum);

        //Make only updates on an existing record, since the records are created by determination process in d365
        if(!lVendTable)
        {
            message = strFmt("Record does not exist",  this.environment, vendTable.ToString());
            throw Error(message);
        }
        else
        {
            message = strFmt("VendTable %1 inserted or found on %2", lVendTable.AccountNum, this.environment);
            response.RecId = lVendTable.RecId;
            response.Success = true;
        }

    }
    catch(ex)
    {
        message = message + "-" + ex.Message;
        response.RecId = 0;
    }

    response.Message = message;
}

/// <summary>
/// Updates or creates corresponding record
/// </summary>
/// <param name = "_record">record instance</param>
/// <returns>Response</returns>
public Niedax.D365.API.Models.D365_APIResponse writeRecord(Niedax.AX.TableRecordModels.TableRecord _record)
{
    this.writeVendTable(_record);
    return response;
}
